CREATE TABLE IF NOT EXISTS trips(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), park_id uuid NOT NULL REFERENCES bus_parks(id), driver_id uuid NOT NULL REFERENCES users(id), state_code char(2) NOT NULL, fare_ngn bigint NOT NULL CHECK(fare_ngn>=0), capacity int NOT NULL CHECK(capacity>=0), departure_at timestamptz NOT NULL, gps_source text NOT NULL DEFAULT 'MANUAL' CHECK(gps_source IN ('HARDWARE','DRIVER_APP','DISPATCHER_APP','MANUAL')), last_capacity_update_at timestamptz, status text NOT NULL DEFAULT 'OPEN');
